package net.civeira.phylax.feature.identity.userprofile.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.identity.userprofile.domain.UserProfile;
import net.civeira.phylax.feature.identity.userprofile.domain.valueobject.MiddleNameVO;

class MiddleNameValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of middle name of user profile")
  void test_middle_name_value_holder_assign_plain_value() {
    Object holder = new Object();
    MiddleNameValueHolder<Object> value = new MiddleNameValueHolder<>(holder);
    Assertions.assertSame(holder, value.middleName("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getMiddleNameValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals("one", value.getMiddleName().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.middleNameNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getMiddleNameValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getMiddleName().isPresent(), "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of middle name of user profile")
  void test_middle_name_value_holder_assign_value_object() {
    Object holder = new Object();
    MiddleNameValueHolder<Object> value = new MiddleNameValueHolder<>(holder);
    MiddleNameVO vo = MiddleNameVO.from("one");
    Assertions.assertFalse(value.getMiddleNameValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.middleName(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getMiddleNameValue().orElseThrow());
    Assertions.assertSame(holder, value.middleName(Optional.empty()));
    Assertions.assertFalse(value.getMiddleNameValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.middleName(Optional.of(vo)));
    Assertions.assertSame(vo, value.getMiddleNameValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of middle name of user profile against the original")
  void test_middle_name_value_holder_read() {
    Object holder = new Object();
    MiddleNameValueHolder<Object> value = new MiddleNameValueHolder<>(holder);
    MiddleNameVO vo = MiddleNameVO.from("one");
    MiddleNameVO other = MiddleNameVO.from("one");
    UserProfile original = Mockito.mock(UserProfile.class);
    Mockito.when(original.getMiddleNameValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readMiddleName(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readMiddleName(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.middleName(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readMiddleName(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readMiddleName(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of middle name of user profile")
  void test_middle_name_value_holder_unset() {
    Object holder = new Object();
    MiddleNameValueHolder<Object> value = new MiddleNameValueHolder<>(holder);
    MiddleNameVO vo = MiddleNameVO.from("one");
    value.middleName(vo);
    Assertions.assertSame(holder, value.unsetMiddleNameIfMatches("middleName_other"));
    Assertions.assertTrue(value.getMiddleNameValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetMiddleNameIfMatches("middleName"));
    Assertions.assertFalse(value.getMiddleNameValue().isPresent(),
        "The field name must clear the value");
    value.middleName(vo);
    Assertions.assertSame(holder, value.unsetMiddleName());
    Assertions.assertFalse(value.getMiddleNameValue().isPresent(), "Unset must clear the value");
  }
}
